const SHAPES: Readonly<Record<string, Shape>> = {"customer_id":{"base":"string","root":"customer_id"},"name":{"base":"string","root":"name"},"customer":{"base":"object","root":"customer","properties":["customer_id","name"]},"peril":{"base":"string","root":"peril"},"limit":{"base":"integer","root":"limit"},"remark":{"base":"string","root":"remark"},"coverage":{"base":"object","root":"coverage","properties":["peril","limit","remark"]},"coverages":{"base":"array","root":"coverages","items":"coverage"},"policy_id":{"base":"string","root":"policy_id"},"holder":{"base":"string","root":"customer_id"},"effective_at":{"base":"string","root":"effective_at"},"expires_at":{"base":"string","root":"expires_at"},"premium":{"base":"integer","root":"premium"},"deductible":{"base":"integer","root":"deductible"},"policy":{"base":"object","root":"policy","properties":["policy_id","holder","coverages","effective_at","expires_at","premium","deductible"]},"policy_issued":{"base":"object","root":"policy_issued","properties":["policy_id","holder","premium"]},"issued":{"base":"object","root":"issued","properties":["policy","policy_issued"]},"stored_policy":{"base":"object","root":"policy","properties":["policy_id","holder","coverages","effective_at","expires_at","premium","deductible"]},"cancelled_at":{"base":"string","root":"cancelled_at"},"cancellation":{"base":"object","root":"cancellation","properties":["stored_policy","cancelled_at"]},"refund":{"base":"integer","root":"refund"},"policy_cancelled":{"base":"object","root":"policy_cancelled","properties":["policy_id","cancelled_at","refund"]},"refund_quote":{"base":"object","root":"refund_quote","properties":["refund","policy_cancelled"]},"refund_refused":{"base":"object","root":"refund_refused","properties":["policy_id","cancelled_at","refund"]},"refund_below_minimum":{"base":"object","root":"refund_below_minimum","properties":["refund","refund_refused"]}};

const REQUIRED: Readonly<Record<string, string>> = {"customer":"Must have customer_id, name","coverage":"Must have peril, limit","policy":"Must have policy_id, holder, coverages, effective_at, expires_at, premium","policy_issued":"Must have policy_id, holder, premium","issued":"Must have policy, policy_issued","cancellation":"Must have stored_policy, cancelled_at","policy_cancelled":"Must have policy_id, cancelled_at, refund","refund_quote":"Must have refund, policy_cancelled","refund_refused":"Must have policy_id, cancelled_at, refund","refund_below_minimum":"Must have refund, refund_refused"};

